// SPDX-License-Identifier: MIT
//! Tests for `chain.zig`'s RFC 5280 §6 path-validation algorithm.
//!
//! The end-to-end tests use real DER certificates from `fixtures_test.zig`
//! (root/intermediate/leaf PKIs generated by a real OpenSSL 3.5 — the test
//! oracle — for every supported signature algorithm plus dedicated
//! rejection-case hierarchies; see that file's doc comment). Every "valid
//! chain" fixture was cross-checked with `openssl verify` at generation
//! time (recorded in the scratch generation script, not part of this repo);
//! these tests re-verify the same DER bytes against THIS module's
//! `verifyChain`, so a pass here means both oracles agree.
//!
//! Sub-algorithm unit tests (`checkPathLength`, `checkNameConstraints`,
//! `checkExtendedKeyUsage`, `parsePssParams`) use hand-built DER fixtures
//! for shapes the openssl-generated certificates don't exercise on their
//! own (e.g. the RFC 4055 all-defaults PSS-params encoding), following the
//! same pattern `extensions.zig`'s own tests already use.

const std = @import("std");
const testing = std.testing;
const chain_mod = @import("chain.zig");
const algorithm = @import("algorithm.zig");
const Certificate = std.crypto.Certificate;
const extensions = @import("extensions.zig");
const rsa = @import("rsa");
const fx = @import("fixtures_test.zig");

// All fixtures were generated with notBefore ~= 2026-07-11T00:00:00Z and
// notAfter ~= 2036-07-08T00:00:00Z (see fixtures_test.zig / the generation
// script's `-days 3650`).
const now_valid: i64 = 1798761600; // 2027-01-01T00:00:00Z
const now_before: i64 = 1262304000; // 2010-01-01T00:00:00Z
const now_after: i64 = 2208988800; // 2040-01-01T00:00:00Z

// ── end-to-end: one valid chain per signature algorithm ─────────────────────

test "valid RSA PKCS1v15 chain verifies (openssl-oracle cross-checked); hostname + EKU positive" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    const result = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{
        .now_sec = now_valid,
        .expected_host = "leaf.example.org",
        .required_eku = .server_auth,
    });
    try testing.expectEqual(@as(u32, 2), result.depth);
    try testing.expectEqual(@as(usize, 0), result.trust_anchor_index);
}

test "valid RSA-PSS chain verifies (root->intermediate link is RSASSA-PSS, exercises verifyPssLink)" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_pss, &fx.inter_pss };
    const anchors = [_]chain_mod.CertDer{&fx.root_pss};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid });
}

test "valid ECDSA P-256 chain verifies (openssl-oracle cross-checked)" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_ec256, &fx.inter_ec256 };
    const anchors = [_]chain_mod.CertDer{&fx.root_ec256};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid });
}

test "valid ECDSA P-384 chain verifies (openssl-oracle cross-checked)" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_ec384, &fx.inter_ec384 };
    const anchors = [_]chain_mod.CertDer{&fx.root_ec384};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid });
}

test "valid Ed25519 chain verifies (openssl-oracle cross-checked)" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_ed, &fx.inter_ed };
    const anchors = [_]chain_mod.CertDer{&fx.root_ed};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid });
}

// ── rejection cases: each maps to a distinct typed error ───────────────────

test "expired leaf rejected with CertificateExpired" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    try testing.expectError(error.CertificateExpired, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_after }));
}

test "not-yet-valid leaf rejected with CertificateNotYetValid" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    try testing.expectError(error.CertificateNotYetValid, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_before }));
}

test "name constraint violation rejected with NameConstraintViolated" {
    // Same intermediate as the valid RSA chain (permits only *.example.org);
    // this leaf's SAN is leaf.evil.com instead.
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa_bad, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    try testing.expectError(error.NameConstraintViolated, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }));
}

test "non-CA certificate used as issuer rejected with NotACertificateAuthority" {
    // subleaf_rsa was (mechanically, via openssl) signed by leaf_rsa's key,
    // even though leaf_rsa's basicConstraints says cA:FALSE.
    const chain = [_]chain_mod.CertDer{ &fx.subleaf_rsa, &fx.leaf_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.inter_rsa};
    try testing.expectError(error.NotACertificateAuthority, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }));
}

test "pathLenConstraint exceeded rejected with PathLenConstraintExceeded" {
    // root_pl has pathlen:0 (no intermediate CAs allowed at all), but the
    // chain has one (inter_pl).
    const chain = [_]chain_mod.CertDer{ &fx.leaf_pl, &fx.inter_pl };
    const anchors = [_]chain_mod.CertDer{&fx.root_pl};
    try testing.expectError(error.PathLenConstraintExceeded, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }));
}

test "self-issued certificate is not counted against pathLenConstraint (positive)" {
    // root_si has pathlen:1. Path: leaf_si -> inter_si -> root_si_prime
    // (self-issued: same subject as root_si, different key, signed BY
    // root_si) -> root_si. Two CA certificates sit between the leaf and the
    // anchor, but root_si_prime is self-issued and must NOT count — only
    // inter_si does, so pathlen:1 is satisfied. A naive implementation that
    // counts both would wrongly reject this with PathLenConstraintExceeded.
    const chain = [_]chain_mod.CertDer{ &fx.leaf_si, &fx.inter_si, &fx.root_si_prime };
    const anchors = [_]chain_mod.CertDer{&fx.root_si};
    const result = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid });
    try testing.expectEqual(@as(u32, 3), result.depth);
}

test "tampered signature byte rejected with CertificateSignatureInvalid" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa_tampered, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    try testing.expectError(error.CertificateSignatureInvalid, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }));
}

test "unknown trust anchor rejected with NoTrustedPath" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{};
    try testing.expectError(error.NoTrustedPath, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }));
}

test "required EKU mismatch rejected with ExtendedKeyUsageMismatch" {
    // leaf_rsa's extKeyUsage is serverAuth only.
    const chain = [_]chain_mod.CertDer{ &fx.leaf_rsa, &fx.inter_rsa };
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    try testing.expectError(error.ExtendedKeyUsageMismatch, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{
        .now_sec = now_valid,
        .required_eku = .client_auth,
    }));
}

test "empty chain rejected with EmptyChain" {
    const chain = [_]chain_mod.CertDer{};
    const anchors = [_]chain_mod.CertDer{&fx.root_rsa};
    try testing.expectError(error.EmptyChain, chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }));
}

// ── checkPathLength ──────────────────────────────────────────────────────

test "checkPathLength: unconstrained always passes" {
    try chain_mod.checkPathLength(null, 0);
    try chain_mod.checkPathLength(null, 1000);
}

test "checkPathLength: within budget passes, exceeded fails" {
    try chain_mod.checkPathLength(2, 0);
    try chain_mod.checkPathLength(2, 2);
    try testing.expectError(error.PathLenConstraintExceeded, chain_mod.checkPathLength(2, 3));
    try testing.expectError(error.PathLenConstraintExceeded, chain_mod.checkPathLength(0, 1));
    try chain_mod.checkPathLength(0, 0);
}

// ── checkNameConstraints ──────────────────────────────────────────────────

/// `GeneralSubtree ::= SEQUENCE { base GeneralName }` wrapping one dNSName
/// base (`[2] IMPLICIT IA5String`, tag 0x82) — the shape
/// `extensions.subtreeIterator` walks. Short-form DER lengths only (test
/// names are always < 128 bytes).
fn dnsSubtree(comptime name: []const u8) [4 + name.len]u8 {
    var buf: [4 + name.len]u8 = undefined;
    buf[0] = 0x30;
    buf[1] = 2 + name.len;
    buf[2] = 0x82;
    buf[3] = name.len;
    for (name, 0..) |c, i| buf[4 + i] = c;
    return buf;
}

/// `GeneralNames ::= SEQUENCE OF GeneralName` wrapping one dNSName entry —
/// the shape `checkNameConstraints`'s `subject_san` parameter expects
/// (same as a real `subjectAltName` extnValue).
fn generalNamesWithDns(comptime name: []const u8) [4 + name.len]u8 {
    var buf: [4 + name.len]u8 = undefined;
    buf[0] = 0x30;
    buf[1] = 2 + name.len;
    buf[2] = 0x82;
    buf[3] = name.len;
    for (name, 0..) |c, i| buf[4 + i] = c;
    return buf;
}

/// Single-entry `GeneralSubtree`/`GeneralNames` wrapping one rfc822Name
/// (`[1] IMPLICIT IA5String`, tag 0x81) — the coinciding shape both a subtree
/// base and a SAN entry take for this type.
fn rfc822Blob(comptime name: []const u8) [4 + name.len]u8 {
    var buf: [4 + name.len]u8 = undefined;
    buf[0] = 0x30;
    buf[1] = 2 + name.len;
    buf[2] = 0x81;
    buf[3] = name.len;
    for (name, 0..) |c, i| buf[4 + i] = c;
    return buf;
}

test "checkNameConstraints: an excluded rfc822Name constraint fails closed (audit F3)" {
    // rfc822Name/URI matching is not implemented; an EXCLUDED constraint of such
    // a type must reject any SAN of that type rather than silently pass (the old
    // fail-open let an excluded email/URI SAN through).
    const excluded_tree = rfc822Blob("evil.example.com");
    const excluded = [_][]const u8{&excluded_tree};
    const permitted = [_][]const u8{};

    const san = rfc822Blob("user@evil.example.com");
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &san));
    // Even an rfc822 SAN not lexically under the excluded base is rejected — we
    // cannot evaluate the match, so we fail closed.
    const san2 = rfc822Blob("user@other.com");
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &san2));
}

test "checkNameConstraints: dNSName label-suffix match, default-deny once a permitted set exists" {
    const subtree = dnsSubtree("example.org");
    const permitted = [_][]const u8{&subtree};
    const excluded = [_][]const u8{};

    // No SAN at all: only the (absent) directoryName constraint applies -> passes.
    try chain_mod.checkNameConstraints(&permitted, &excluded, "irrelevant subject dn", "");

    // SAN dNSName "www.example.org" -> matches the permitted suffix.
    const good = generalNamesWithDns("www.example.org");
    try chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &good);

    // SAN dNSName "evilexample.org" -> same trailing bytes as a raw
    // substring, but NOT on a label boundary; must NOT match.
    const bad = generalNamesWithDns("evilexample.org");
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &bad));

    // SAN dNSName "example.net" -> different domain entirely, no permitted
    // subtree covers it (a permitted dNSName set exists, so this is a
    // default-deny, not merely "unconstrained").
    const other = generalNamesWithDns("example.net");
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &other));
}

test "checkNameConstraints: excluded wins even when a name would also be permitted" {
    const permitted_tree = dnsSubtree("example.org");
    const excluded_tree = dnsSubtree("bad.example.org");
    const permitted = [_][]const u8{&permitted_tree};
    const excluded = [_][]const u8{&excluded_tree};

    // Within the permitted domain overall, but also within the excluded subdomain.
    const name = generalNamesWithDns("host.bad.example.org");
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &name));

    // Within the permitted domain, outside the excluded subdomain -> passes.
    const ok_name = generalNamesWithDns("host.example.org");
    try chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &ok_name);
}

test "checkNameConstraints: no constraints at all always passes" {
    const permitted = [_][]const u8{};
    const excluded = [_][]const u8{};
    const name = generalNamesWithDns("anything.example.com");
    try chain_mod.checkNameConstraints(&permitted, &excluded, "any subject dn", &name);
}

test "checkNameConstraints: iPAddress CIDR containment" {
    // base = 10.0.0.0/255.255.0.0 (a /16), i.e. addr=10.0.0.0 mask=255.255.0.0
    const subtree_content = [_]u8{ 0x30, 10, 0x87, 8, 10, 0, 0, 0, 255, 255, 0, 0 };
    const permitted = [_][]const u8{&subtree_content};
    const excluded = [_][]const u8{};

    const in_range = [_]u8{ 0x30, 6, 0x87, 4, 10, 0, 55, 66 };
    try chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &in_range);

    const out_of_range = [_]u8{ 0x30, 6, 0x87, 4, 10, 1, 55, 66 };
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, "dn", &out_of_range));
}

test "checkNameConstraints: directoryName RDN-sequence prefix containment" {
    // `dnMatchesPrefix` matches generic DER elements one at a time (the
    // encoded byte span of each successive "RDN" must be identical) — it
    // doesn't need real X.501 AttributeTypeAndValue structure to exercise
    // the prefix-containment algorithm itself, so plain OCTET STRING
    // elements stand in for RDNs here.
    const rdn_org = [_]u8{ 0x04, 3, 'O', 'r', 'g' }; // one "RDN": "Org"
    const rdn_sub = [_]u8{ 0x04, 3, 'S', 'u', 'b' }; // another: "Sub"
    const rdn_other = [_]u8{ 0x04, 5, 'O', 't', 'h', 'e', 'r' };

    const base = rdn_org; // base DN = [Org]
    const name_prefixed = rdn_org ++ rdn_sub; // name DN = [Org, Sub] -> base is a strict prefix
    const name_unrelated = rdn_other ++ rdn_sub; // name DN = [Other, Sub] -> base is NOT a prefix

    // `permitted`/`excluded` are raw `GeneralSubtrees` blobs (`SEQUENCE OF
    // GeneralSubtree`, `GeneralSubtree ::= SEQUENCE { base GeneralName }`) —
    // NOT the bare RDN content on its own. `base` (the constraint's
    // directoryName) must be wrapped in the `[4] Name` CHOICE tag (0xa4)
    // and then in the `GeneralSubtree` SEQUENCE tag (0x30), matching exactly
    // what `subtreeIterator`/`SubtreeIterator.next` expect to walk — feeding
    // it the unwrapped `base` alone previously crashed the parser (it tried
    // to read `base`'s own 5 bytes as if they were an outer `GeneralSubtree`
    // SEQUENCE, then walked off the end looking for a nested `base` inside).
    const base_general_name = [_]u8{ 0xa4, base.len } ++ base;
    const general_subtree = [_]u8{ 0x30, base_general_name.len } ++ base_general_name;
    const permitted = [_][]const u8{&general_subtree};
    const excluded = [_][]const u8{};

    // directoryName is CHOICE-tagged `[4] Name` — context-specific,
    // constructed (identifier byte 0xa4) — wrapped in an outer
    // `GeneralNames SEQUENCE` for feeding to `checkNameConstraints`.
    //
    // `checkNameConstraints` always ALSO checks the subject DN itself against
    // any accumulated directoryName constraint (see the two calls below this
    // block), so these SAN-focused checks pass `&name_prefixed` (which
    // itself satisfies the permitted base) as the subject DN — isolating
    // what's under test here to the SAN entry's own good/bad match, not a
    // spurious subject_dn violation.
    const good_entry = [_]u8{ 0xa4, name_prefixed.len } ++ name_prefixed;
    const good = [_]u8{ 0x30, good_entry.len } ++ good_entry;
    try chain_mod.checkNameConstraints(&permitted, &excluded, &name_prefixed, &good);

    const bad_entry = [_]u8{ 0xa4, name_unrelated.len } ++ name_unrelated;
    const bad = [_]u8{ 0x30, bad_entry.len } ++ bad_entry;
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, &name_prefixed, &bad));

    // The subject DN itself is always checked against directoryName
    // constraints too, independent of any SAN.
    try chain_mod.checkNameConstraints(&permitted, &excluded, &name_prefixed, "");
    try testing.expectError(error.NameConstraintViolated, chain_mod.checkNameConstraints(&permitted, &excluded, &name_unrelated, ""));
}

// ── checkExtendedKeyUsage ──────────────────────────────────────────────────

// ExtKeyUsageSyntax ::= SEQUENCE OF KeyPurposeId, one OID: serverAuth (1.3.6.1.5.5.7.3.1).
const eku_server_auth = [_]u8{ 0x30, 0x0a, 0x06, 0x08, 0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x01 };
// ...clientAuth (1.3.6.1.5.5.7.3.2).
const eku_client_auth = [_]u8{ 0x30, 0x0a, 0x06, 0x08, 0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x02 };
// ...anyExtendedKeyUsage (2.5.29.37.0).
const eku_any = [_]u8{ 0x30, 0x06, 0x06, 0x04, 0x55, 0x1d, 0x25, 0x00 };

test "checkExtendedKeyUsage: required=null is a no-op regardless of EKUs present" {
    const intermediates = [_]?[]const u8{&eku_client_auth};
    try chain_mod.checkExtendedKeyUsage(&intermediates, &eku_client_auth, null);
}

test "checkExtendedKeyUsage: leaf EKU must include the required purpose" {
    const intermediates = [_]?[]const u8{null};
    try chain_mod.checkExtendedKeyUsage(&intermediates, &eku_server_auth, .server_auth);
    try testing.expectError(
        error.ExtendedKeyUsageMismatch,
        chain_mod.checkExtendedKeyUsage(&intermediates, &eku_client_auth, .server_auth),
    );
}

test "checkExtendedKeyUsage: leaf EKU absent is unrestricted" {
    const intermediates = [_]?[]const u8{null};
    try chain_mod.checkExtendedKeyUsage(&intermediates, null, .server_auth);
}

test "checkExtendedKeyUsage: an intermediate's EKU must permit the leaf purpose too" {
    const bad_intermediates = [_]?[]const u8{&eku_client_auth};
    try testing.expectError(
        error.ExtendedKeyUsageMismatch,
        chain_mod.checkExtendedKeyUsage(&bad_intermediates, &eku_server_auth, .server_auth),
    );

    const any_intermediates = [_]?[]const u8{&eku_any};
    try chain_mod.checkExtendedKeyUsage(&any_intermediates, &eku_server_auth, .server_auth);
}

// ── parsePssParams (RFC 4055 §3.1) ──────────────────────────────────────────

test "parsePssParams: null params (AlgorithmIdentifier omitted parameters) -> RFC 4055 defaults" {
    const params = try chain_mod.parsePssParams(null);
    try testing.expectEqual(@as(usize, 20), params.salt_len);
}

test "parsePssParams: empty SEQUENCE (all fields omitted) -> RFC 4055 defaults (sha1, salt 20)" {
    const empty_seq = [_]u8{ 0x30, 0x00 };
    const params = try chain_mod.parsePssParams(&empty_seq);
    try testing.expectEqual(@as(usize, 20), params.salt_len);
}

test "parsePssParams: explicit sha256/MGF1-sha256/saltLen 32 (matches openssl's own encoding)" {
    // RSASSA-PSS-params ::= SEQUENCE {
    //   hashAlgorithm    [0] { SEQUENCE { OID sha256 } },
    //   maskGenAlgorithm [1] { SEQUENCE { OID mgf1, SEQUENCE { OID sha256 } } },
    //   saltLength       [2] { INTEGER 32 },
    // }
    const sha256_alg = [_]u8{ 0x30, 0x0b, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01 };
    const hash_field = [_]u8{ 0xa0, sha256_alg.len } ++ sha256_alg;

    const mgf1_alg = [_]u8{ 0x30, 0x18, 0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x08 } ++ sha256_alg;
    const mgf_field = [_]u8{ 0xa1, mgf1_alg.len } ++ mgf1_alg;

    const salt_field = [_]u8{ 0xa2, 0x03, 0x02, 0x01, 32 };

    const content = hash_field ++ mgf_field ++ salt_field;
    const seq = [_]u8{ 0x30, content.len } ++ content;

    const params = try chain_mod.parsePssParams(&seq);
    try testing.expectEqual(@as(usize, 32), params.salt_len);
}

test "parsePssParams: mismatched digest vs MGF1 inner hash rejected (this module's documented restriction)" {
    const sha256_alg = [_]u8{ 0x30, 0x0b, 0x06, 0x09, 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01 };
    const sha1_alg = [_]u8{ 0x30, 0x07, 0x06, 0x05, 0x2b, 0x0e, 0x03, 0x02, 0x1a };
    const hash_field = [_]u8{ 0xa0, sha256_alg.len } ++ sha256_alg; // hashAlgorithm = sha256

    // mgf1-OID element (11 bytes) ++ sha1_alg (9 bytes) = 20-byte content.
    const mgf1_alg = [_]u8{ 0x30, 0x14, 0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x08 } ++ sha1_alg; // MGF1 inner hash = sha1 (mismatch)
    const mgf_field = [_]u8{ 0xa1, mgf1_alg.len } ++ mgf1_alg;

    const content = hash_field ++ mgf_field;
    const seq = [_]u8{ 0x30, content.len } ++ content;

    try testing.expectError(error.UnsupportedPssParams, chain_mod.parsePssParams(&seq));
}

// ── ML-DSA (RFC 9881): the algorithms std's table cannot name ──────────────
//
// These hierarchies are `@embedFile`d DER rather than byte literals like the
// rest of `fixtures_test.zig`: an ML-DSA-87 certificate is 7.5 KB, and three
// full chains as hex arrays would be some 3000 lines of generated source for
// no benefit. `data/*.der` are the exact bytes OpenSSL 3.5.5 emitted.
//
// Same oracle discipline as every hierarchy above: each chain was accepted by
// `openssl verify -CAfile root -untrusted inter leaf` at generation time, and
// these tests re-verify the same bytes through THIS module. A pass means both
// implementations agree; `verifyChain` reaching them at all is what the OID
// map in `algorithm.zig` bought.

const mldsa = struct {
    const root44 = @embedFile("data/root_mldsa44.der");
    const inter44 = @embedFile("data/inter_mldsa44.der");
    const leaf44 = @embedFile("data/leaf_mldsa44.der");
    const root65 = @embedFile("data/root_mldsa65.der");
    const inter65 = @embedFile("data/inter_mldsa65.der");
    const leaf65 = @embedFile("data/leaf_mldsa65.der");
    const root87 = @embedFile("data/root_mldsa87.der");
    const inter87 = @embedFile("data/inter_mldsa87.der");
    const leaf87 = @embedFile("data/leaf_mldsa87.der");
    /// An ML-DSA-65 CA whose subject DN is byte-identical to the ML-DSA-44
    /// intermediate's, so path building accepts it as `leaf44`'s issuer and
    /// the parameter-set check is the only thing standing in the way.
    const impostor65 = @embedFile("data/impostor_mldsa65.der");
};

// The ML-DSA fixtures were generated later than the rest, so they carry their
// own validity window (notBefore 2026-08-22, `-days 3650`).
const now_valid_mldsa: i64 = 1798761600; // 2027-01-01T00:00:00Z

test "valid ML-DSA-44 chain verifies (openssl-oracle cross-checked)" {
    const chain = [_]chain_mod.CertDer{ mldsa.leaf44, mldsa.inter44 };
    const anchors = [_]chain_mod.CertDer{mldsa.root44};
    const result = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa });
    try testing.expectEqual(@as(u32, 2), result.depth);
}

test "valid ML-DSA-65 chain verifies (openssl-oracle cross-checked); hostname + EKU positive" {
    const chain = [_]chain_mod.CertDer{ mldsa.leaf65, mldsa.inter65 };
    const anchors = [_]chain_mod.CertDer{mldsa.root65};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{
        .now_sec = now_valid_mldsa,
        .expected_host = "leaf.example.org",
        .required_eku = .server_auth,
    });
}

test "valid ML-DSA-87 chain verifies (openssl-oracle cross-checked)" {
    const chain = [_]chain_mod.CertDer{ mldsa.leaf87, mldsa.inter87 };
    const anchors = [_]chain_mod.CertDer{mldsa.root87};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa });
}

test "ML-DSA: an issuer key of the wrong parameter set is named, not mistaken for corruption" {
    // Without the parameter-set check in `verifyMlDsaLink`, this reaches the
    // length comparison instead: an ML-DSA-65 key is 1952 bytes where 44
    // wants 1312, so the failure would surface as CertificatePublicKeyInvalid
    // and read like a damaged certificate rather than the algorithm confusion
    // it is.
    // Checked through `verifyMlDsaLink` directly: `verifyChain`'s path
    // builder collapses a failed trust-anchor candidate into NoTrustedPath,
    // which would hide exactly the distinction under test.
    try testing.expectError(
        error.CertificateSignatureAlgorithmMismatch,
        chain_mod.verifyMlDsaLink(mldsa.leaf44, mldsa.impostor65, now_valid_mldsa),
    );

    // And the same call with the RIGHT issuer succeeds, so the test above is
    // not passing for some unrelated reason.
    try chain_mod.verifyMlDsaLink(mldsa.leaf44, mldsa.inter44, now_valid_mldsa);
}

test "ML-DSA: a leaf presented to the wrong parameter set's anchor finds no path" {
    // The three hierarchies are independent, so their DNs differ and this
    // never reaches a signature check at all — it covers path building, not
    // `verifyMlDsaLink`. The test above is the one that reaches the
    // parameter-set comparison.
    const chain = [_]chain_mod.CertDer{ mldsa.leaf44, mldsa.inter87 };
    const anchors = [_]chain_mod.CertDer{mldsa.root87};
    try testing.expectError(
        error.NoTrustedPath,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa }),
    );
}

test "ML-DSA: a tampered tbsCertificate is rejected, not ignored" {
    // Guards the shape where a signature is decoded and then never checked
    // against the message. Deliberately NOT a flipped signature byte: that is
    // caught by `Signature.fromBytes`'s own encoding validation, so such a
    // test passes even with the `verify` call deleted — verified by mutation.
    // Editing the signed bytes instead can only be caught by verification.
    var tampered: [mldsa.leaf65.len]u8 = mldsa.leaf65.*;
    const cn = std.mem.indexOf(u8, &tampered, "leaf.example.org").?;
    tampered[cn] = 'x'; // same length, so the DER stays structurally valid

    const chain = [_]chain_mod.CertDer{ &tampered, mldsa.inter65 };
    const anchors = [_]chain_mod.CertDer{mldsa.root65};
    try testing.expectError(
        error.CertificateSignatureInvalid,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa }),
    );
}

test "ML-DSA: expiry and not-yet-valid are checked on the ML-DSA path too" {
    const chain = [_]chain_mod.CertDer{ mldsa.leaf65, mldsa.inter65 };
    const anchors = [_]chain_mod.CertDer{mldsa.root65};
    try testing.expectError(
        error.CertificateNotYetValid,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_before }),
    );
    try testing.expectError(
        error.CertificateExpired,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_after }),
    );
}

test "ML-DSA: the result reports the algorithm std cannot name, and says so by nulling leaf" {
    const chain = [_]chain_mod.CertDer{ mldsa.leaf65, mldsa.inter65 };
    const anchors = [_]chain_mod.CertDer{mldsa.root65};
    const result = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa });

    // `leaf` is std's view, and std has no name for ML-DSA. Null rather than
    // a `Parsed` whose `signature_algorithm` says sha256WithRSAEncryption.
    try testing.expect(result.leaf == null);
    try testing.expectEqual(algorithm.MlDsa.ml_dsa_65, result.leaf_pub_key_algo.ml_dsa);
    try testing.expectEqualSlices(u8, mldsa.leaf65, result.leaf_der);
}

test "classic algorithms keep std's parsed leaf — nulling is specific, not blanket" {
    const chain = [_]chain_mod.CertDer{ &fx.leaf_ed, &fx.inter_ed };
    const anchors = [_]chain_mod.CertDer{&fx.root_ed};
    const result = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid });

    try testing.expect(result.leaf != null);
    try testing.expectEqual(Certificate.AlgorithmCategory.curveEd25519, result.leaf_pub_key_algo.toStd().?);
}

test "ML-DSA: a wrong hostname is still rejected on the synthesized-name path" {
    // The hostname check for an ML-DSA leaf runs against `hostNameView`, not
    // against `Certificate.parse`. A view that returned empty name fields
    // would reject everything and look like it worked; the positive case is
    // the ML-DSA-65 test above, and this is its negative half.
    const chain = [_]chain_mod.CertDer{ mldsa.leaf65, mldsa.inter65 };
    const anchors = [_]chain_mod.CertDer{mldsa.root65};
    try testing.expectError(error.CertificateHostMismatch, chain_mod.verifyChain(
        testing.allocator,
        &chain,
        &anchors,
        .{ .now_sec = now_valid_mldsa, .expected_host = "not-the-leaf.example.org" },
    ));
}

// ── SLH-DSA (RFC 9882): twelve parameter sets, all of them checked ─────────
//
// Coverage is deliberately two-tier, and the split is stated rather than
// implied. Two FULL hierarchies — one per hash family — carry the path logic
// and the X.509 encoding assumptions. Twelve SELF-SIGNED certificates, one
// per parameter set, carry the OID-to-parameter-set wiring: a self-signed
// certificate is a link whose issuer is itself, so `verifySlhDsaLink` on it
// exercises exactly the lookup, the length checks and the verification.
//
// Not twelve full hierarchies: an SLH-DSA-SHAKE-256f certificate is 50 KB,
// so that would be 1.2 MB of fixtures to re-prove path building eleven more
// times. Every one of the fourteen certificates was accepted by
// `openssl verify` at generation time.

const slh = struct {
    const root_sha2 = @embedFile("data/root_slh_sha2_128s.der");
    const inter_sha2 = @embedFile("data/inter_slh_sha2_128s.der");
    const leaf_sha2 = @embedFile("data/leaf_slh_sha2_128s.der");
    const root_shake = @embedFile("data/root_slh_shake_128s.der");
    const inter_shake = @embedFile("data/inter_slh_shake_128s.der");
    const leaf_shake = @embedFile("data/leaf_slh_shake_128s.der");

    /// One self-signed certificate per FIPS 205 parameter set, in the same
    /// order `algorithm.SlhDsa` declares them.
    const selfsigned = [_][]const u8{
        @embedFile("data/slh_self_sha2_128s.der"),
        @embedFile("data/slh_self_sha2_128f.der"),
        @embedFile("data/slh_self_sha2_192s.der"),
        @embedFile("data/slh_self_sha2_192f.der"),
        @embedFile("data/slh_self_sha2_256s.der"),
        @embedFile("data/slh_self_sha2_256f.der"),
        @embedFile("data/slh_self_shake_128s.der"),
        @embedFile("data/slh_self_shake_128f.der"),
        @embedFile("data/slh_self_shake_192s.der"),
        @embedFile("data/slh_self_shake_192f.der"),
        @embedFile("data/slh_self_shake_256s.der"),
        @embedFile("data/slh_self_shake_256f.der"),
    };
};

test "valid SLH-DSA-SHA2-128s chain verifies (openssl-oracle cross-checked); hostname + EKU positive" {
    const chain = [_]chain_mod.CertDer{ slh.leaf_sha2, slh.inter_sha2 };
    const anchors = [_]chain_mod.CertDer{slh.root_sha2};
    const result = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{
        .now_sec = now_valid_mldsa,
        .expected_host = "leaf.example.org",
        .required_eku = .server_auth,
    });
    try testing.expectEqual(@as(u32, 2), result.depth);
    try testing.expect(result.leaf == null);
    try testing.expectEqual(algorithm.SlhDsa.sha2_128s, result.leaf_pub_key_algo.slh_dsa);
}

test "valid SLH-DSA-SHAKE-128s chain verifies (the other hash family)" {
    const chain = [_]chain_mod.CertDer{ slh.leaf_shake, slh.inter_shake };
    const anchors = [_]chain_mod.CertDer{slh.root_shake};
    _ = try chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa });
}

test "SLH-DSA: all twelve parameter sets verify, each against its own OID" {
    // A self-signed certificate is a link whose issuer is itself. Any
    // mis-wiring between OID, parameter set and implementation fails here:
    // the wrong `Impl` gives the wrong lengths for ten of the twelve, and for
    // the `s`/`f` pair that shares a key length it gives a false signature.
    for (slh.selfsigned, 0..) |cert, i| {
        errdefer std.debug.print("parameter set index {d}\n", .{i});
        try chain_mod.verifySlhDsaLink(cert, cert, now_valid_mldsa);
    }
}

test "SLH-DSA: every self-signed fixture reports the parameter set its OID names" {
    const order = [_]algorithm.SlhDsa{
        .sha2_128s,  .sha2_128f,  .sha2_192s,  .sha2_192f,  .sha2_256s,  .sha2_256f,
        .shake_128s, .shake_128f, .shake_192s, .shake_192f, .shake_256s, .shake_256f,
    };
    // Guards the fixture list itself: a duplicated or misordered @embedFile
    // would still pass the test above, since every entry would verify — just
    // not as the set the list claims.
    for (slh.selfsigned, order) |cert, want| {
        const anchors = [_]chain_mod.CertDer{cert};
        const one = [_]chain_mod.CertDer{cert};
        const result = try chain_mod.verifyChain(testing.allocator, &one, &anchors, .{ .now_sec = now_valid_mldsa });
        try testing.expectEqual(want, result.leaf_pub_key_algo.slh_dsa);
    }
}

test "SLH-DSA: a tampered tbsCertificate is rejected, not ignored" {
    var tampered: [slh.leaf_sha2.len]u8 = slh.leaf_sha2.*;
    const cn = std.mem.indexOf(u8, &tampered, "leaf.example.org").?;
    tampered[cn] = 'x';

    const chain = [_]chain_mod.CertDer{ &tampered, slh.inter_sha2 };
    const anchors = [_]chain_mod.CertDer{slh.root_sha2};
    try testing.expectError(
        error.CertificateSignatureInvalid,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid_mldsa }),
    );
}

test "SLH-DSA: mixing the two hash families at the same size is an algorithm mismatch" {
    // SHA2-128s and SHAKE-128s have IDENTICAL key and signature lengths, so
    // every length check passes and only the parameter-set comparison stands
    // between them. Without it this reaches verification and returns a bare
    // false, reported as a forged signature rather than the confusion it is.
    try testing.expectError(
        error.CertificateSignatureAlgorithmMismatch,
        chain_mod.verifySlhDsaLink(slh.leaf_sha2, slh.root_shake, now_valid_mldsa),
    );
}

// ── regression: zero-length BIT STRINGs reach parseShape before anything is
//    verified (audit 2026-09-01) ─────────────────────────────────────────────
//
// `parseShape` leans on `std.crypto.Certificate.parseBitString`, which reads
// the unused-bits octet without checking the BIT STRING has one and returns
// `start + 1` regardless. Both call sites take attacker-controlled elements,
// and `verifyChain` reaches the first of them on the peer's leaf certificate
// before a single signature is checked — so the shapes below used to abort the
// process (Debug/ReleaseSafe) or produce a slice of length 2^32-1 (ReleaseFast).

const oid_sha256rsa_tlv = [_]u8{ 0x30, 0x0d, 0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b, 0x05, 0x00 };
const validity_tlv = [_]u8{ 0x30, 0x1e, 0x17, 0x0d } ++ "250101000000Z".* ++
    [_]u8{ 0x17, 0x0d } ++ "350101000000Z".*;
const rsa_algid_tlv = [_]u8{ 0x30, 0x0d, 0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01, 0x05, 0x00 };

/// A structurally complete certificate whose `subjectPublicKeyInfo` BIT STRING
/// and `signatureValue` are supplied by the caller, so a test can make either
/// one degenerate while every enclosing element stays well-formed.
fn craftCert(comptime pub_key_bits: []const u8, comptime signature_bits: []const u8) []const u8 {
    const spki_body = rsa_algid_tlv ++ pub_key_bits[0..pub_key_bits.len].*;
    const spki = [_]u8{ 0x30, spki_body.len } ++ spki_body;
    const tbs_body = [_]u8{ 0xa0, 0x03, 0x02, 0x01, 0x02 } ++ // version v3
        [_]u8{ 0x02, 0x01, 0x01 } ++ // serialNumber
        oid_sha256rsa_tlv ++ // signature
        [_]u8{ 0x30, 0x00 } ++ // issuer
        validity_tlv ++
        [_]u8{ 0x30, 0x00 } ++ // subject
        spki;
    const tbs = [_]u8{ 0x30, tbs_body.len } ++ tbs_body;
    const body = tbs ++ oid_sha256rsa_tlv ++ signature_bits[0..signature_bits.len].*;
    return &([_]u8{ 0x30, body.len } ++ body);
}

test "regression: a zero-length signatureValue BIT STRING is a typed error, not a panic" {
    const cert = comptime craftCert(&[_]u8{ 0x03, 0x02, 0x00, 0x00 }, &[_]u8{ 0x03, 0x00 });
    const chain = [_]chain_mod.CertDer{cert};
    const anchors = [_]chain_mod.CertDer{cert};
    try testing.expectError(
        error.CertificateHasInvalidBitString,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }),
    );
}

test "regression: a zero-length subjectPublicKey BIT STRING is a typed error, not a panic" {
    const cert = comptime craftCert(&[_]u8{ 0x03, 0x00 }, &[_]u8{ 0x03, 0x02, 0x00, 0x00 });
    const chain = [_]chain_mod.CertDer{cert};
    const anchors = [_]chain_mod.CertDer{cert};
    try testing.expectError(
        error.CertificateHasInvalidBitString,
        chain_mod.verifyChain(testing.allocator, &chain, &anchors, .{ .now_sec = now_valid }),
    );
}

test "PQ single-link helpers chain the issuer's name, like their std counterpart" {
    // `verifyMlDsaLink`/`verifySlhDsaLink` are public and documented as the
    // way to check one link without building a path. The std function they
    // stand in for, `Parsed.verify`, rejects an issuer whose subject DN is not
    // the subject's issuer DN (RFC 5280 §6.1.3 (a)(4)); these used to verify
    // the signature and return success regardless, so the parity the doc
    // comment advertises was not there.
    //
    // The mutation is same-length, so the DER stays well-formed and the
    // issuer's key is untouched — only its subject DN changes.
    var forged: [mldsa.inter44.len]u8 = mldsa.inter44.*;
    const needle = "Test Inter ML-DSA-44";
    try testing.expectEqual(@as(usize, 1), std.mem.count(u8, &forged, needle));
    forged[std.mem.indexOf(u8, &forged, needle).?] = 'X';
    try testing.expectError(
        error.CertificateIssuerMismatch,
        chain_mod.verifyMlDsaLink(mldsa.leaf44, &forged, now_valid_mldsa),
    );
    // Unmutated, the same link still verifies — so the test is pinning the
    // name check, not a broken fixture.
    try chain_mod.verifyMlDsaLink(mldsa.leaf44, mldsa.inter44, now_valid_mldsa);

    var forged_slh: [slh.inter_sha2.len]u8 = slh.inter_sha2.*;
    const needle_slh = "Test Inter SLH-DSA";
    try testing.expectEqual(@as(usize, 1), std.mem.count(u8, &forged_slh, needle_slh));
    forged_slh[std.mem.indexOf(u8, &forged_slh, needle_slh).?] = 'X';
    try testing.expectError(
        error.CertificateIssuerMismatch,
        chain_mod.verifySlhDsaLink(slh.leaf_sha2, &forged_slh, now_valid_mldsa),
    );
    try chain_mod.verifySlhDsaLink(slh.leaf_sha2, slh.inter_sha2, now_valid_mldsa);
}

// ── the two length checks each PQ path makes before coercing a slice to an
//    array, and the SLH-DSA validity window (audit 2026-09-01) ──────────────
//
// SPEC claimed each of the ML-DSA path's four checks was pinned by a test that
// goes red when the check alone is removed. Two were not: deleting either
// length check left the whole suite green. They matter more than bookkeeping —
// they stand in front of `key_bytes[0..encoded_length].*` and
// `signature[0..encoded_length].*`, which in ReleaseFast would otherwise read
// up to 4627 bytes past the certificate buffer and feed them to verification.

/// Rewrite every occurrence of one algorithm OID's content bytes with
/// another's. The two are always the same length (they differ in the final
/// arc), so the DER stays byte-for-byte well-formed and only the algorithm
/// *names* change — which is exactly the confusion these checks exist to
/// catch. Blanket replacement is safe here because neither `verifyMlDsaLink`
/// nor `verifySlhDsaLink` reads the issuer's own signatureAlgorithm or the
/// subject's own SubjectPublicKeyInfo.
fn renameAlgorithm(gpa: std.mem.Allocator, cert: []const u8, from: []const u8, to: []const u8) ![]u8 {
    std.debug.assert(from.len == to.len);
    const out = try gpa.dupe(u8, cert);
    errdefer gpa.free(out);
    var replaced: usize = 0;
    var i: usize = 0;
    while (std.mem.indexOfPos(u8, out, i, from)) |at| {
        @memcpy(out[at..][0..to.len], to);
        i = at + to.len;
        replaced += 1;
    }
    // A rename that matched nothing would make the test vacuous.
    try testing.expect(replaced > 0);
    return out;
}

const oid_mldsa44 = [_]u8{ 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x03, 0x11 };
const oid_mldsa65 = [_]u8{ 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x03, 0x12 };
const oid_slh_sha2_128s = [_]u8{ 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x03, 0x14 };
const oid_slh_sha2_128f = [_]u8{ 0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x03, 0x15 };

test "ML-DSA: a public key whose length is not the parameter set's is rejected by length" {
    // Both halves of a real ML-DSA-65 link, renamed to claim ML-DSA-44. The
    // parameter sets now agree with each other, and the names still chain, so
    // the 1952-byte key reaching a slot that fixes 1312 is the only thing left
    // to catch.
    const gpa = testing.allocator;
    const subject = try renameAlgorithm(gpa, mldsa.leaf65, &oid_mldsa65, &oid_mldsa44);
    defer gpa.free(subject);
    const issuer = try renameAlgorithm(gpa, mldsa.inter65, &oid_mldsa65, &oid_mldsa44);
    defer gpa.free(issuer);
    try testing.expectError(
        error.CertificatePublicKeyInvalid,
        chain_mod.verifyMlDsaLink(subject, issuer, now_valid_mldsa),
    );
}

test "SLH-DSA: a signature whose length is not the parameter set's is rejected by length" {
    // SHA2-128s and SHA2-128f share a 32-byte public key and differ only in
    // signature size (7856 vs 17088), so renaming a self-signed 128s
    // certificate to 128f passes the parameter-set comparison, passes the
    // name chaining (it is self-signed) and passes the key-length check —
    // leaving the signature-length check alone on the line. Without it the
    // short signature reaches `slhdsa.verify`, which returns a bare `false`
    // that reads as a forgery rather than a size mismatch.
    const gpa = testing.allocator;
    const renamed = try renameAlgorithm(gpa, slh.selfsigned[0], &oid_slh_sha2_128s, &oid_slh_sha2_128f);
    defer gpa.free(renamed);
    try testing.expectError(
        error.CertificateSignatureInvalidLength,
        chain_mod.verifySlhDsaLink(renamed, renamed, now_valid_mldsa),
    );
}

test "SLH-DSA: expiry and not-yet-valid are checked on the SLH-DSA path too" {
    // The ML-DSA path had this test; the SLH-DSA path did not, while SPEC
    // described the two as "the same shape" — a parity of assurance the suite
    // did not deliver.
    try testing.expectError(
        error.CertificateNotYetValid,
        chain_mod.verifySlhDsaLink(slh.leaf_sha2, slh.inter_sha2, now_before),
    );
    try testing.expectError(
        error.CertificateExpired,
        chain_mod.verifySlhDsaLink(slh.leaf_sha2, slh.inter_sha2, now_after),
    );
}
